create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, friend_code text not null unique check (friend_code ~ '^[0-9]{6}$'), name text not null default '' check (char_length(name) <= 30), created_at timestamptz not null default now());
alter table public.profiles enable row level security;
create table public.friendships (requester uuid not null references public.profiles(id) on delete cascade, addressee uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','accepted')), created_at timestamptz not null default now(), primary key (requester, addressee), check (requester <> addressee));
alter table public.friendships enable row level security;
create or replace function public.require_account() returns uuid language plpgsql stable as $$ begin if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then raise exception 'login_required'; end if; return auth.uid(); end; $$;
create or replace function public.ensure_profile(p_name text) returns table(friend_code text, name text) language plpgsql security definer set search_path = public as $$ #variable_conflict use_column
declare me uuid := public.require_account(); c text; begin if not exists (select 1 from profiles where id = me) then loop c := lpad(floor(random() * 1000000)::int::text, 6, '0'); exit when not exists (select 1 from profiles p where p.friend_code = c); end loop; insert into profiles (id, friend_code, name) values (me, c, left(coalesce(p_name, ''), 30)); elsif coalesce(p_name, '') <> '' then update profiles set name = left(p_name, 30) where id = me; end if; return query select p.friend_code, p.name from profiles p where p.id = me; end; $$;
create or replace function public.send_friend_request(p_code text) returns text language plpgsql security definer set search_path = public as $$ declare me uuid := public.require_account(); other uuid; st text; begin select id into other from profiles where friend_code = regexp_replace(coalesce(p_code, ''), '[^0-9]', '', 'g'); if other is null then return 'not_found'; end if; if other = me then return 'self'; end if; select status into st from friendships where requester = other and addressee = me; if st = 'pending' then update friendships set status = 'accepted' where requester = other and addressee = me; return 'accepted'; end if; if st = 'accepted' or exists (select 1 from friendships where requester = me and addressee = other) then return 'exists'; end if; if (select count(*) from friendships where requester = me and status = 'pending') >= 50 then return 'too_many'; end if; insert into friendships (requester, addressee) values (me, other); return 'sent'; end; $$;
create or replace function public.respond_friend_request(p_other uuid, p_accept boolean) returns void language plpgsql security definer set search_path = public as $$ declare me uuid := public.require_account(); begin if p_accept then update friendships set status = 'accepted' where requester = p_other and addressee = me and status = 'pending'; else delete from friendships where requester = p_other and addressee = me and status = 'pending'; end if; end; $$;
create or replace function public.remove_friend(p_other uuid) returns void language plpgsql security definer set search_path = public as $$ declare me uuid := public.require_account(); begin delete from friendships where (requester = me and addressee = p_other) or (requester = p_other and addressee = me); end; $$;
create or replace function public.list_friends() returns table(id uuid, name text, friend_code text, kind text, since timestamptz) language sql security definer set search_path = public as $$ select p.id, p.name, case when f.status = 'accepted' then p.friend_code else null end, case when f.status = 'accepted' then 'friend' when f.addressee = public.require_account() then 'incoming' else 'outgoing' end, f.created_at from friendships f join profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end where f.requester = public.require_account() or f.addressee = auth.uid() order by f.created_at desc; $$;
revoke all on function public.require_account() from public;
revoke all on function public.ensure_profile(text) from public;
revoke all on function public.send_friend_request(text) from public;
revoke all on function public.respond_friend_request(uuid, boolean) from public;
revoke all on function public.remove_friend(uuid) from public;
revoke all on function public.list_friends() from public;
grant execute on function public.require_account() to authenticated;
grant execute on function public.ensure_profile(text) to authenticated;
grant execute on function public.send_friend_request(text) to authenticated;
grant execute on function public.respond_friend_request(uuid, boolean) to authenticated;
grant execute on function public.remove_friend(uuid) to authenticated;
grant execute on function public.list_friends() to authenticated;
